const request = $json.body ?? {};
const header = $json.headers?.['x-stocksense-agent-secret'];
if (!header || header !== $env.AGENT_SERVICE_SECRET) throw new Error('Agent service authentication failed');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (request.version !== '1.0' || !request.requestId || !uuid.test(request.conversationId ?? '') || typeof request.message !== 'string' || !request.message.trim() || request.message.length > 2000 || !request.userContextRef || !['MANAGER','STAFF'].includes(request.role)) throw new Error('Invalid chat request envelope');
return [{ json: { ...request, message: request.message.trim() } }];

const envelope = $('Validate trusted envelope').first().json;
const unavailable = (message) => [{ json: { ...envelope, callTool: false, direct: { version:'1.0', requestId:envelope.requestId, conversationId:envelope.conversationId, kind:'unavailable', message, citationsToToolResults:[], meta:{ intent:'PROVIDER_ERROR', tool:null } } } }];
if ($json.error || !$json.candidates?.length) return unavailable('I cannot reach the language service right now. Please try again; normal inventory screens are still available.');
const text = $json.candidates[0]?.content?.parts?.map(part => part.text ?? '').join('');
let intent; try { intent = JSON.parse(text); } catch { return unavailable('I could not safely understand that request. Please try rephrasing it.'); }
const base = $env.BACKEND_INTERNAL_URL || 'http://host.docker.internal:3000/internal/v1/agent-tools';
const end = new Date(); const start = new Date(end.getTime() - 7 * 86400000);
const range = { from: intent.from || start.toISOString(), to: intent.to || end.toISOString(), limit: intent.limit || 5 };
let tool = null; let toolBody = { contextRef: envelope.userContextRef };
if (intent.intent === 'STOCK_QUERY' && intent.productQuery) { tool='stock-levels'; toolBody.query=intent.productQuery; }
if (intent.intent === 'LOW_STOCK_QUERY') tool='low-stock';
if (intent.intent === 'TOP_SELLING_QUERY') { tool='top-selling'; Object.assign(toolBody, range); }
if (intent.intent === 'FINANCIAL_QUERY' && envelope.role === 'MANAGER') { tool='financial-summary'; Object.assign(toolBody, range); }
if (intent.intent === 'FINANCIAL_QUERY' && envelope.role !== 'MANAGER') return [{json:{...envelope,callTool:false,direct:{version:'1.0',requestId:envelope.requestId,conversationId:envelope.conversationId,kind:'refusal',message:'Financial cost, margin, and profit information is available to managers only.',citationsToToolResults:[],meta:{intent:intent.intent,tool:null}}}}];
if (intent.intent === 'MOVEMENT_REQUEST') { if(!intent.productQuery || !intent.movementType || !Number.isInteger(intent.quantity) || intent.quantity < 1) return [{json:{...envelope,callTool:false,direct:{version:'1.0',requestId:envelope.requestId,conversationId:envelope.conversationId,kind:'refusal',message:'Please include an exact product name or SKU, movement action, and positive whole-number quantity.',citationsToToolResults:[],meta:{intent:intent.intent,tool:null}}}}]; tool='prepare-movement'; toolBody={contextRef:envelope.userContextRef,productQuery:intent.productQuery,movementType:intent.movementType,quantity:intent.quantity,supplierName:intent.supplierName,reason:intent.reason,idempotencyKey:envelope.requestId}; }
if (!tool) return [{json:{...envelope,callTool:false,direct:{version:'1.0',requestId:envelope.requestId,conversationId:envelope.conversationId,kind:'refusal',message:'I can help with stock levels, low-stock items, top-selling products, and safe stock-change proposals.',citationsToToolResults:[],meta:{intent:intent.intent,tool:null}}}}];
return [{json:{...envelope,intent:intent.intent,callTool:true,tool,toolUrl:base+'/'+tool,toolBody}}];

const route = $('Authorize intent and select tool').first().json;
const response = (kind,message,citations=[],proposal) => [{json:{version:'1.0',requestId:route.requestId,conversationId:route.conversationId,kind,message,citationsToToolResults:citations,meta:{intent:route.intent,tool:route.tool},...(proposal?{proposal}:{})}}];
if ($json.error || !$json.data) { const detail=$json.error?.message; return response('refusal',detail || 'The inventory tool could not safely prepare that request. Please check the product, quantity, supplier, and available stock.'); }
const data=$json.data; const citation=data.toolResultId?[data.toolResultId]:[];
if(route.tool==='prepare-movement'){const p=data.proposal;return response('proposal',`I prepared a ${p.movementType.toLowerCase().replaceAll('_',' ')} proposal for ${p.quantity} ${p.product.name}. Review it carefully before confirming.`,citation,p);}
if (route.tool==='stock-levels') { const items=data.items??[]; if(!items.length)return response('answer','I could not find an active product matching that name or SKU.',citation); return response('answer',items.map(p=>`${p.name} (${p.sku}) has ${p.quantity} unit${p.quantity===1?'':'s'} on hand${p.isLowStock?' and is at or below its low-stock threshold':''}.`).join('\n'),citation); }
if(route.tool==='low-stock'){const items=data.items??[];if(!items.length)return response('answer','No active products are currently at or below their low-stock thresholds.',citation);return response('answer',`There ${items.length===1?'is':'are'} ${items.length} low-stock ${items.length===1?'product':'products'}:\n`+items.map(p=>`• ${p.name} (${p.sku}): ${p.quantity} on hand; threshold ${p.lowStockThreshold}`).join('\n'),citation);}
if(route.tool==='top-selling'){const items=data.items??[];if(!items.length)return response('answer','No sales were recorded in that period.',citation);return response('answer','Top-selling products for the requested period:\n'+items.map((r,i)=>`${i+1}. ${r.product.name} (${r.product.sku}) — ${r.unitsSold} sold`).join('\n'),citation);}
if(route.tool==='financial-summary'){const pkr=n=>new Intl.NumberFormat('en-PK',{style:'currency',currency:'PKR',maximumFractionDigits:0}).format(n/100);return response('answer',`For the requested period: ${data.unitsSold} units sold, revenue ${pkr(data.revenueMinor)}, cost ${pkr(data.costMinor)}, and gross profit ${pkr(data.profitMinor)}.`,citation);}
return response('unavailable','The tool returned an unsupported result.');
